"use client";
import {useState} from "react"; import Header from "@/components/Header"; import Footer from "@/components/Footer"; import Hero from "@/components/Hero"; import {projects,img} from "@/components/siteData";
export default function Projects(){const [filter,setFilter]=useState("All Projects");const cats=["All Projects","Water Supply","Drainage & Sewerage","Agriculture","Infrastructure","Residential","Industrial","Tanks & Storage"];const filtered=filter==="All Projects"?projects:projects.filter(p=>p[1]===filter);return <><Header/><Hero eyebrow="PROJECTS" title="OUR PROJECTS" description="Building a stronger and more sustainable Philippines with reliable piping and water storage solutions." image={img.infrastructure}/><section className="projects-page"><div className="project-filters">{cats.map(c=><button key={c} className={filter===c?"filter active":"filter"} onClick={()=>setFilter(c)}>{c}</button>)}<input placeholder="Search projects..."/></div><div className="projects-grid">{filtered.map(([title,,location,image,description])=><article className="project-card" key={title}><img src={image} alt={title}/><div className="project-card-body"><h3>{title}</h3><div className="location">📍 {location}</div><p>{description}</p><a href="#">View Project →</a></div></article>)}</div></section><section className="solution-bottom"><div><h2>Partner with Us for a Stronger Tomorrow</h2><p>Let's build better communities with reliable piping and water storage solutions.</p></div><a href="/request-a-quote" className="blue-button">Request a Quote →</a><a href="/contact" className="outline-blue-button">Contact Our Team</a></section><Footer/></>}
